пр = json.loads(B.виклик('паспорт', json.dumps(dict(json_моделі='```json\n'+відп+'\n```', сценарій=вх['сценарій'], вимоги=слова), ensure_ascii=False)))
п = пр['паспорт']; print('\nПАСПОРТ:', json.dumps(п, ensure_ascii=False)[:600]); print('ВИПАДОК СЛОВАМИ:', пр['випадок'])
вх2 = dict(вх, паспорт=п, вимоги=слова)
