print('за бажанням у пул:', [(x['слот'], x['назва'][:40], x['бажання'][:20]) for x in r['за_бажанням']])
print('поломка руки 2:', r['мета']['плацебо']['чим_розведено'], '| випадок у промпті руки 1:', re.search(r'ВИПАДОК[^\n]*', r['руки']['1']).group(0)[:160])
print('ВИМОГИ в руці 1:', (re.search(r'ВИМОГИ[^\n]*\n[^\n]*\n[^\n]*', r['руки']['1']) or re.search(r'Хоче:[^\n]*', r['руки']['1'])).group(0)[:300])
