к = r['кандидати']; ном,_ = PL.номери_речей(к)
print('комплекти у верх/низ:', sum(1 for сл in ('верх','низ') for x in к.get(сл,[]) if x.get('слот')=='комплект'), '| чобіт у взутті:', sum(1 for x in к['взуття'] if re.search('чобот|угг',x['назва'],re.I)))
