print('\nІТЕРАЦІЯ 1 (JSON): образів', len(в1['образи']))
for i,о in enumerate(в1['образи'],1):
    print(' ', i, о.get('підпис'), '| речей', len(о['ід']), '| слоти', [ (x.get('слот'), x.get('частина_комплекту')) for x in (о.get('речі') or [])][:4], '| блокує', (о.get('блокує') or [])[:2], '| невідомі', о.get('невідомі'))
print('запропоновано на «потрібно»:', [(x['слот'], x['назва'][:45]) for x in в1['запропоновано']])
i = в1['промпт_ремонту'].find('На твої запити'); print('у промпті ремонту:', в1['промпт_ремонту'][i:i+300].replace('\n',' | '))
print('формат ремонту JSON:', '"образи": [' in в1['промпт_ремонту'], '| знахідок з «утримано»:', 'утримано' in в1['промпт_ремонту'], '| K-CRA-04 у знахідках:', any(z.get('правило')=='K-CRA-04' for о in в1['образи'] for z in (о.get('знахідки') or [])))
# ІТЕРАЦІЯ 3: вибір JSON
відп3 = json.dumps(dict(підпис='обраний', чому='бо пасує', речі=в1['образи'][0]['ід'][:0] or []), ensure_ascii=False)
ід0 = [тег(компл['id'])+'/верх', тег(низ['id']), тег(вз['id']), тег(см['id'])]
в3 = json.loads(B.виклик('від_моделі', json.dumps(dict(вх2, донор=False, текст_моделі=json.dumps(dict(підпис='обраний', чому='бо пасує', речі=ід0), ensure_ascii=False)), ensure_ascii=False)))
print('\nІТЕРАЦІЯ 3 (вибір JSON): перевірено', в3.get('перевірено'), '| речей', len(в3.get('речі') or []), '| частина:', [(x['id'][:14], x.get('частина_комплекту')) for x in в3['речі'] if x.get('частина_комплекту')])
о = json.loads(B.виклик('опис', json.dumps(dict(вх2, речі=[x['id'] for x in в3['речі']], підпис='обраний', свідомі=[], частини={компл['id']:'верх'}), ensure_ascii=False)))
print('ОПИС згадує половину:', 'із комплекту' in о['промпт'], '| випадок в описі:', re.search(r'ВИПАДОК[^\n]*', о['промпт']).group(0)[:120])
print('\nбриф руки 1: рядки тісність/прилягання/K-CRA-04:', [p.get('ярлик') for p in r['правила_рук']['B'] if p.get('ярлик') in ('тісність','прилягання') or p.get('правило')=='K-CRA-04'])
